"""Audit feedback generated by the real resume analysis pipeline.

Evaluates evidence-grounded resume feedback across single or multiple
synthetic candidate profiles.

This is an LLM-judge audit: generated items do not have human-verified
reference labels. The judge output is an automated assessment, not
ground truth.
"""

import argparse
import asyncio
import json
import logging
import sys
import time
from collections import Counter, defaultdict
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from app.integrations.llm.base import LLMError
from app.modules.resume.feedback_quality_judge import FeedbackQualityJudge
from app.modules.resume.schemas import ResumeAnalysisRequest
from app.modules.resume.service import ResumeAnalysisService

BASE_DIR = Path(__file__).resolve().parent.parent
FIXTURE_DIR = BASE_DIR / "tests" / "fixtures"
OUTPUT_DIR = BASE_DIR / "eval_results"

DIMENSIONS = ("grounded", "relevant", "actionable")
SECTIONS = (
    "strengths",
    "improvement_suggestions",
    "likely_interview_questions",
)

logger = logging.getLogger(__name__)


def check_evidence_alignment_violations(
    analysis_strengths: list[str],
    prohibited_keywords: list[str],
) -> list[dict[str, str]]:
    """Flag any strengths that praise skills or achievements that were not demonstrated."""
    violations: list[dict[str, str]] = []
    for strength in analysis_strengths:
        strength_lower = strength.lower()
        for kw in prohibited_keywords:
            if kw.lower() in strength_lower:
                violations.append({
                    "strength_item": strength,
                    "prohibited_keyword": kw,
                    "issue": f"Strength mentions non-demonstrated concept '{kw}'",
                })
    return violations


async def evaluate_single_profile(
    profile_id: str,
    pdf_bytes: bytes,
    resume_text: str,
    job_role: str,
    job_description: str,
    service: ResumeAnalysisService,
    judge: FeedbackQualityJudge | None,
    expected_evidence: dict[str, str] | None = None,
    expected_matched_skills: list[str] | None = None,
    prohibited_keywords: list[str] | None = None,
) -> dict[str, Any]:
    """Run real pipeline and audit one profile."""
    request = ResumeAnalysisRequest(
        job_role=job_role,
        job_description=job_description,
    )

    start_time = time.perf_counter()
    analysis = await service.analyze(pdf_bytes, request)
    elapsed_seconds = round(time.perf_counter() - start_time, 2)

    # 1. Deterministic checks
    deterministic_checks: dict[str, Any] = {
        "matched_skills": analysis.matched_skills,
        "missing_skills": analysis.missing_skills,
        "match_score": analysis.match_score,
        "evidence_alignment_violations": [],
    }

    if expected_matched_skills is not None:
        deterministic_checks["matched_skills_match_expected"] = (
            sorted(analysis.matched_skills) == sorted(expected_matched_skills)
        )

    if prohibited_keywords:
        violations = check_evidence_alignment_violations(
            analysis.strengths,
            prohibited_keywords,
        )
        deterministic_checks["evidence_alignment_violations"] = violations

    # 2. Item-level judge evaluation
    feedback_items = [
        (section, item)
        for section in SECTIONS
        for item in getattr(analysis, section)
    ]

    item_results: list[dict[str, Any]] = []
    section_metrics: dict[str, dict[str, Any]] = {}

    for section in SECTIONS:
        items = getattr(analysis, section)
        section_metrics[section] = {
            "total_items": len(items),
            "grounded_count": 0,
            "relevant_count": 0,
            "actionable_count": 0,
        }

    for index, (section, item) in enumerate(feedback_items, start=1):
        case = {
            "resume_text": resume_text,
            "job_role": analysis.job_role,
            "section": section,
            "feedback_item": item,
        }

        judge_prediction = None
        if judge is not None:
            try:
                judge_prediction = await judge.evaluate(case)
            except (LLMError, ValueError) as exc:
                logger.warning(
                    "Judge failed on %s item %d: %s", profile_id, index, exc
                )
                judge_prediction = {
                    "grounded": None,
                    "relevant": None,
                    "actionable": None,
                    "reasoning": {"error": str(exc)},
                }

        if judge_prediction:
            for dim in DIMENSIONS:
                if judge_prediction.get(dim) is True:
                    section_metrics[section][f"{dim}_count"] += 1

        item_results.append({
            "item_id": f"{profile_id}_{index:03d}",
            "section": section,
            "feedback_item": item,
            "judge": judge_prediction,
        })

    # Summary counts for profile
    total_items = len(item_results)
    profile_label_counts = {
        dim: {
            "true": sum(
                r["judge"].get(dim) is True
                for r in item_results
                if r.get("judge")
            ),
            "false": sum(
                r["judge"].get(dim) is False
                for r in item_results
                if r.get("judge")
            ),
            "unrated": sum(
                r.get("judge") is None or r["judge"].get(dim) is None
                for r in item_results
            ),
        }
        for dim in DIMENSIONS
    }

    return {
        "profile_id": profile_id,
        "job_role": job_role,
        "latency_seconds": elapsed_seconds,
        "item_count": total_items,
        "section_item_counts": {s: len(getattr(analysis, s)) for s in SECTIONS},
        "deterministic_checks": deterministic_checks,
        "section_metrics": section_metrics,
        "judge_label_counts": profile_label_counts,
        "analysis": analysis.model_dump(),
        "items": item_results,
    }


async def run_evaluation(
    manifest_path: Path | None = None,
    single: bool = False,
    skip_judge: bool = False,
):
    service = ResumeAnalysisService()
    judge = None if skip_judge else FeedbackQualityJudge()

    job_desc_path = FIXTURE_DIR / "sample_job_description.txt"
    default_job_desc = (
        job_desc_path.read_text(encoding="utf-8")
        if job_desc_path.exists()
        else "Junior Machine Learning Engineer"
    )

    profiles_to_evaluate: list[dict[str, Any]] = []

    if single:
        pdf_path = FIXTURE_DIR / "sample_resume.pdf"
        txt_path = FIXTURE_DIR / "sample_resume.txt"
        profiles_to_evaluate.append({
            "profile_id": "single_sample_resume",
            "pdf_bytes": pdf_path.read_bytes(),
            "resume_text": txt_path.read_text(encoding="utf-8"),
            "job_role": "Junior Machine Learning Engineer",
            "job_description": default_job_desc,
            "expected_matched_skills": None,
            "expected_evidence": None,
            "prohibited_keywords": None,
        })
    else:
        if manifest_path is None:
            manifest_path = (
                FIXTURE_DIR
                / "synthetic_profiles"
                / "synthetic_profiles_manifest.json"
            )

        if not manifest_path.exists():
            raise FileNotFoundError(f"Manifest not found: {manifest_path}")

        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        fixtures_dir = manifest_path.parent

        for p_def in manifest.get("profiles", []):
            base_name = p_def["file_base"]
            pdf_file = fixtures_dir / f"{base_name}.pdf"
            txt_file = fixtures_dir / f"{base_name}.txt"

            if not pdf_file.exists() or not txt_file.exists():
                raise FileNotFoundError(
                    f"Profile fixture files missing for {base_name}"
                )

            profiles_to_evaluate.append({
                "profile_id": p_def["profile_id"],
                "pdf_bytes": pdf_file.read_bytes(),
                "resume_text": txt_file.read_text(encoding="utf-8"),
                "job_role": p_def.get(
                    "job_role", "Junior Machine Learning Engineer"
                ),
                "job_description": default_job_desc,
                "expected_matched_skills": p_def.get("expected_matched_skills"),
                "expected_evidence": p_def.get("expected_evidence"),
                "prohibited_keywords": p_def.get(
                    "prohibited_strength_keywords"
                ),
            })

    print(
        f"Starting evaluation across {len(profiles_to_evaluate)} profile(s)..."
    )
    profile_results = []
    total_violations = 0

    for idx, p in enumerate(profiles_to_evaluate, start=1):
        p_id = p["profile_id"]
        print(f"\n--- [{idx}/{len(profiles_to_evaluate)}] Evaluating {p_id} ---")
        try:
            res = await evaluate_single_profile(
                profile_id=p_id,
                pdf_bytes=p["pdf_bytes"],
                resume_text=p["resume_text"],
                job_role=p["job_role"],
                job_description=p["job_description"],
                service=service,
                judge=judge,
                expected_evidence=p.get("expected_evidence"),
                expected_matched_skills=p.get("expected_matched_skills"),
                prohibited_keywords=p.get("prohibited_keywords"),
            )
            violations = res["deterministic_checks"][
                "evidence_alignment_violations"
            ]
            total_violations += len(violations)
            print(
                f"  Latency: {res['latency_seconds']}s | Items: {res['item_count']} | "
                f"Violations: {len(violations)}"
            )
            profile_results.append(res)
        except Exception as exc:
            logger.exception("Failed evaluation on profile %s", p_id)
            profile_results.append({
                "profile_id": p_id,
                "error": str(exc),
                "status": "failed",
            })

    # Summary report
    completed = [p for p in profile_results if "error" not in p]
    total_items = sum(p["item_count"] for p in completed)

    summary = {
        "suite_evaluation_completed_at": datetime.now(timezone.utc).isoformat(),
        "total_profiles_attempted": len(profiles_to_evaluate),
        "total_profiles_successful": len(completed),
        "total_feedback_items_generated": total_items,
        "total_evidence_alignment_violations": total_violations,
        "generator_provider": type(service.llm).__name__,
        "judge_provider": type(judge.llm).__name__ if judge else "None",
        "profiles": profile_results,
    }

    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    out_file = (
        OUTPUT_DIR / "generated_resume_feedback_audit.json"
        if single
        else OUTPUT_DIR / "multi_profile_resume_feedback_audit.json"
    )
    out_file.write_text(
        json.dumps(summary, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    print(f"\nAudit complete. Detailed report saved to: {out_file}")
    print(f"Total evidence alignment violations: {total_violations}")
    return summary


def main():
    parser = argparse.ArgumentParser(
        description="Evaluate resume feedback pipeline across candidate profiles."
    )
    parser.add_argument(
        "--manifest",
        type=Path,
        default=None,
        help="Path to synthetic_profiles_manifest.json",
    )
    parser.add_argument(
        "--single",
        action="store_true",
        help="Run single legacy sample_resume fixture",
    )
    parser.add_argument(
        "--skip-judge",
        action="store_true",
        help="Skip LLM judge evaluation (deterministic checks only)",
    )
    args = parser.parse_args()

    logging.basicConfig(level=logging.INFO)
    asyncio.run(
        run_evaluation(
            manifest_path=args.manifest,
            single=args.single,
            skip_judge=args.skip_judge,
        )
    )


if __name__ == "__main__":
    main()
